package net.officefloor.hq.app.history;

import com.fasterxml.jackson.annotation.JsonAutoDetect.Visibility;
import com.fasterxml.jackson.annotation.PropertyAccessor;
import jakarta.persistence.PostPersist;
import jakarta.persistence.PostRemove;
import jakarta.persistence.PostUpdate;
import java.sql.Date;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.person.Patron;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Statement;
import net.officefloor.hq.app.person.Watch;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.role.Delegation;
import net.officefloor.hq.app.role.SheetRole;
import net.officefloor.hq.app.sheet.Sheet;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;
import tools.jackson.databind.DeserializationFeature;
import tools.jackson.databind.json.JsonMapper;

/**
 * The versions of a sheet, its people, their claims, its rates, its periods, the statements taken, the
 * patrons named, the watches kept, the roles given and the delegations made: each change keeps the state it left the
 * row in, with the sheet's today when it was made, so the rows can be read back as of a date — as the
 * changes made while the sheet's today was on or before it left them, each row's latest such change by the
 * order they were made, a change made later not counting whatever its today.
 * Kept by the entities' listener once the change is written, in the same transaction.
 */
@Component
public class History {

    private final JdbcTemplate jdbc;
    private final JsonMapper json = JsonMapper.builder()
            .changeDefaultVisibility(v -> v.withVisibility(PropertyAccessor.ALL, Visibility.NONE)
                    .withVisibility(PropertyAccessor.FIELD, Visibility.ANY))
            .disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES)
            .build();

    public History(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    @PostPersist
    @PostUpdate
    public void saved(Object entity) {
        keep(entity, json.writeValueAsString(entity));
    }

    @PostRemove
    public void removed(Object entity) {
        keep(entity, null);
-- Each change to a sheet, its people, their claims and its rates keeps the state it left the row in, with
-- the sheet's today when it was made (none for a row removed), so a statement can be taken as of a date:
-- the rows as the changes made while the sheet's today was on or before it left them. Oldest first (by id).
-- Rows changed before this was kept have no versions.
CREATE TABLE entity_version (
    id          BIGINT       GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    sheet_id    VARCHAR(200) NOT NULL,
    kind        VARCHAR(20)  NOT NULL,
    entity_id   VARCHAR(200) NOT NULL,
    recorded_on DATE         NOT NULL,
    state       CLOB
);
CREATE INDEX entity_version_sheet ON entity_version (sheet_id, kind, recorded_on);
-- The user whose editor is open on a claim, locking it for every other user until they save or cancel
-- it, or the sheet's today changes; none while unlocked.
ALTER TABLE claim ADD COLUMN locked_by VARCHAR(200);
# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}

